const SECOND_VERDICT_SIGNATURE=['二番手の断罪',26,6,'発動地点から照準方向へ長さ500・半幅22の射線を固定。0.7秒後、その時点で射線に入っている敵を手前から選び、1体目へ80%、2体目へ420%の一撃。3体目以降には当たらず、1体だけなら80%。途中の壁は貫通しない。移動しても射線は動かないが、起点から500を超える・起点が壁越しになると解除。範囲補正は射線幅だけに適用。属性抽選で対象順・威力配分は変わらない。','M8 43L45 6M12 34L22 44M25 18L39 32M35 5H47V17M5 35L13 43'];
SIGNATURE_SKILLS.push(SECOND_VERDICT_SIGNATURE);Object.assign(GEM.crafted_5_2,{name:SECOND_VERDICT_SIGNATURE[0],cost:26,cool:6,desc:SECOND_VERDICT_SIGNATURE[3],ability:null,signature:98,tags:['spell','area']});
SIGNATURE_AUDIO.push(['secondverdict',830,.3]);SKILL_AUDIO_FAMILIES.metal.add('secondverdict');
function secondVerdictValid(s){return s.owner===p&&s.world===dungeon&&!s.finished&&!dead&&p?.hp>0&&dist(p,s.origin)<=500&&lineClear(p,s.origin);}
function secondVerdictTargets(s){let ux=Math.cos(s.angle),uy=Math.sin(s.angle),width=22*s.build.radius;return enemies.filter(e=>e.hp>0).map((e,index)=>{let dx=e.x-s.origin.x,dy=e.y-s.origin.y;return{e,index,along:dx*ux+dy*uy,side:Math.abs(dx*uy-dy*ux)};}).filter(q=>q.along>=0&&q.along<=s.length&&q.side<=width&&lineClear(s.origin,q.e)).sort((a,b)=>a.along-b.along||a.index-b.index).slice(0,2).map(q=>q.e);}
const secondVerdictCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{let result=secondVerdictCastBase(build,...args);if(GEM[build.type]?.signature!==98)return result;let s=signatureSpells.at(-1);if(s?.mode!==98)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==98||v===s);s.owner=p;s.world=dungeon;s.finished=false;s.target=null;s.length=0;for(let d=5;d<=500;d+=5){let q={x:s.origin.x+Math.cos(s.angle)*d,y:s.origin.y+Math.sin(s.angle)*d};if(!lineClear(s.origin,q))break;s.length=d;}s.end={x:s.origin.x+Math.cos(s.angle)*s.length,y:s.origin.y+Math.sin(s.angle)*s.length};return result;};
const secondVerdictStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==98)return secondVerdictStepBase(s,dt);if(!secondVerdictValid(s))return false;if(paused||!Number.isFinite(dt)||dt<=0)return true;s.time+=dt;if(s.time+1e-8<.7)return true;let targets=secondVerdictTargets(s);s.finished=true;for(let [i,e]of targets.entries())if(e.hp>0&&enemies.includes(e)){spellHit(e,s.damage*(i===0?.8:4.2),s.build);burst(e.x,e.y,i?70:30,ELEMENTS[s.build.elements[0]].color);}playSignatureAudio(98,true,s.origin.x,s.origin.y);return false;};
const secondVerdictPaintBase=paintSignatureSpells;paintSignatureSpells=()=>{secondVerdictPaintBase();for(let s of signatureSpells){if(s.mode!==98||!secondVerdictValid(s)||!visibleAt(s.origin.x,s.origin.y))continue;let color=ELEMENTS[s.build.elements[0]].color,width=22*s.build.radius,nx=-Math.sin(s.angle)*width,ny=Math.cos(s.angle)*width;for(let side of [-1,1])paintLinkLine({x:s.origin.x+nx*side,y:s.origin.y+ny*side},{x:s.end.x+nx*side,y:s.end.y+ny*side},color,1);paintLinkLine(s.origin,s.end,color,2);for(let [i,e]of secondVerdictTargets(s).entries())if(visibleAt(e.x,e.y))groundRing(e.x,e.y,i?34:20,i?'#ffe4b0':color,i?3:1);}};
const secondVerdictStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===98?{label:'二番手',value:Math.min(1,s.time/.7),waiting:true}:secondVerdictStatusBase(s);
